// Resolve the in-progress NFL season, its prior season, and the latest completed
// week from nflverse games.csv. Drives the stats-release URLs and the rating week.
const raw = (() => { try { return $('Get Games CSV').first().json.data || ''; } catch (e) { return ''; } })();
const lines = raw.trim().split(/\r?\n/).filter(Boolean);
if (lines.length < 2) {
  const y = new Date().getFullYear();
  return [{ json: { season: y, prior_season: y - 1, week: 1, _no_schedule: true } }];
}
const header = lines[0].split(','); const idx = {}; header.forEach((h, i) => { idx[h.trim()] = i; });
const col = (c, n) => { const i = idx[n]; return i === undefined ? '' : (c[i] == null ? '' : String(c[i]).trim()); };
const rows = lines.slice(1).map(l => l.split(',')).filter(c => c.length >= header.length);

const now = Date.now();
const pd = s => s ? new Date(s + 'T17:00:00Z').getTime() : null;
const seasons = [...new Set(rows.map(c => parseInt(col(c, 'season'), 10)).filter(n => !isNaN(n)))].sort((a, b) => b - a);
let season = seasons[0] || new Date().getFullYear();
for (const s of seasons) {
  const ds = rows.filter(c => parseInt(col(c, 'season'), 10) === s).map(c => pd(col(c, 'gameday'))).filter(Boolean);
  if (!ds.length) continue;
  const first = Math.min(...ds), last = Math.max(...ds), wk = 7 * 864e5;
  if (now >= first - wk && now <= last + wk) { season = s; break; }
}
const sg = rows.filter(c => parseInt(col(c, 'season'), 10) === season);
const completed = sg.filter(c => col(c, 'home_score') !== '');
const week = completed.length ? Math.max(...completed.map(c => parseInt(col(c, 'week'), 10)).filter(n => !isNaN(n))) : 1;

return [{ json: { season, prior_season: season - 1, week } }];

// ===== NFL power-rating math (pure; no n8n globals) =====
// computeRatings(curStatsCsv, priorStatsCsv, gamesCsv, season, priorSeason)
//   curStatsCsv / priorStatsCsv : nflverse stats_team_week CSVs (offense per team-week)
//   gamesCsv                    : nflverse games.csv (for prior-season line calibration)
// Rating = points vs league average: opponent-adjusted (SRS) net EPA/play, scaled
// by K (calibrated on the prior season's closing lines), regressed toward last
// season's rating with weight w = g/(g+8) so early weeks lean on the prior.
const REG_CONST = 8;          // pseudo-games of prior weight; w = g/(g+REG_CONST)
const K_FALLBACK = 28.9;      // pts per 1.0 net EPA/play if calibration is unavailable

const canonTeam = t => ({ LAR: 'LA', OAK: 'LV', SD: 'LAC', STL: 'LA', WSH: 'WAS' }[t] || t);

// RFC-4180 field split (quote-aware).
function splitLine(line) {
  const out = []; let f = '', q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += ch; }
    else if (ch === '"') q = true;
    else if (ch === ',') { out.push(f); f = ''; }
    else f += ch;
  }
  out.push(f); return out;
}
function csvRows(csv) {
  const lines = (csv || '').trim().split(/\r?\n/).filter(Boolean);
  if (lines.length < 2) return { header: [], idx: {}, rows: [] };
  const header = splitLine(lines[0]);
  const idx = {}; header.forEach((h, i) => { idx[h.trim()] = i; });
  return { header, idx, rows: lines.slice(1).map(l => splitLine(l)) };
}

// stats_team_week -> [{week, team, opp, offEPA, offPlays}] (regular season only)
function parseStats(csv) {
  const { idx, rows } = csvRows(csv);
  const num = (c, k) => { const v = parseFloat(c[idx[k]]); return isNaN(v) ? 0 : v; };
  const out = [];
  let maxWeek = 0;
  for (const c of rows) {
    if (idx.season_type !== undefined && c[idx.season_type] !== 'REG') continue;
    const week = parseInt(c[idx.week], 10);
    if (isNaN(week)) continue;
    maxWeek = Math.max(maxWeek, week);
    out.push({
      week,
      team: canonTeam(c[idx.team]),
      opp: canonTeam(c[idx.opponent_team]),
      offEPA: num(c, 'passing_epa') + num(c, 'rushing_epa'),
      offPlays: num(c, 'attempts') + num(c, 'carries') + num(c, 'sacks_suffered'),
    });
  }
  return { plays: out, maxWeek };
}

// opponent-adjusted per-play net EPA (SRS), plus raw off/def per play and games
function adjRatings(plays) {
  const off = {};                                // off[week][team] = {epa, plays}
  for (const r of plays) (off[r.week] ??= {})[r.team] = { epa: r.offEPA, plays: r.offPlays };
  const teams = {};
  for (const r of plays) {
    const T = (teams[r.team] ??= { oE: 0, oP: 0, dE: 0, dP: 0, opps: [], g: 0 });
    T.oE += r.offEPA; T.oP += r.offPlays;
    const oo = off[r.week][r.opp];               // allowed = opponent's offense that week
    if (oo) { T.dE += oo.epa; T.dP += oo.plays; }
    T.opps.push(r.opp); T.g++;
  }
  for (const t in teams) {
    const T = teams[t];
    T.off_pp = T.oP ? T.oE / T.oP : 0;
    T.def_pp = T.dP ? T.dE / T.dP : 0;
    T.net = T.off_pp - T.def_pp;
    T.adj = T.net;
  }
  const list = Object.keys(teams);
  for (let i = 0; i < 25; i++) {
    const nx = {};
    for (const t of list) {
      const T = teams[t];
      const sos = T.opps.length ? T.opps.reduce((s, o) => s + (teams[o] ? teams[o].adj : 0), 0) / T.opps.length : 0;
      nx[t] = T.net + sos;
    }
    const mean = list.reduce((s, t) => s + nx[t], 0) / list.length;
    for (const t of list) teams[t].adj = nx[t] - mean;   // recenter to league avg 0
  }
  return teams;
}

// K = slope of prior-season closing lines vs opponent-adjusted rating difference
function calibrateK(priorTeams, gamesCsv, priorSeason) {
  const { idx, rows } = csvRows(gamesCsv);
  if (idx.spread_line === undefined) return K_FALLBACK;
  const pts = [];
  for (const c of rows) {
    if (parseInt(c[idx.season], 10) !== priorSeason) continue;
    const sl = parseFloat(c[idx.spread_line]);
    if (isNaN(sl)) continue;
    const home = canonTeam(c[idx.home_team]), away = canonTeam(c[idx.away_team]);
    if (!priorTeams[home] || !priorTeams[away]) continue;
    pts.push({ x: priorTeams[home].adj - priorTeams[away].adj, y: sl });
  }
  if (pts.length < 20) return K_FALLBACK;
  const mean = a => a.reduce((s, v) => s + v, 0) / a.length;
  const mx = mean(pts.map(p => p.x)), my = mean(pts.map(p => p.y));
  const sxy = pts.reduce((s, p) => s + (p.x - mx) * (p.y - my), 0);
  const sxx = pts.reduce((s, p) => s + (p.x - mx) ** 2, 0);
  if (sxx === 0) return K_FALLBACK;
  const k = sxy / sxx;
  return (k > 10 && k < 60) ? k : K_FALLBACK;      // guard against a degenerate fit
}

const round = (v, d) => { const p = Math.pow(10, d); return Math.round(v * p) / p; };

function computeRatings(curStatsCsv, priorStatsCsv, gamesCsv, season, priorSeason) {
  const curParsed = parseStats(curStatsCsv);
  const cur = adjRatings(curParsed.plays);
  const prior = adjRatings(parseStats(priorStatsCsv).plays);
  const K = calibrateK(prior, gamesCsv, priorSeason);
  const week = curParsed.maxWeek || 1;

  const rows = [];
  for (const t of Object.keys(cur)) {
    const g = cur[t].g;
    const w = g / (g + REG_CONST);
    const priorPts = (prior[t] ? prior[t].adj : 0) * K;
    const curPts = cur[t].adj * K;
    const rating = (1 - w) * priorPts + w * curPts;
    rows.push({
      season, week, team: t,
      off_epa: round(cur[t].off_pp, 4),
      def_epa: round(cur[t].def_pp, 4),
      rating: round(rating, 2),
      games_played: g,
    });
  }
  rows.sort((a, b) => b.rating - a.rating);
  return { rows, K: round(K, 2), week };
}

// Export for the unit test (Node); harmless in the n8n code node.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { computeRatings, adjRatings, parseStats, calibrateK, canonTeam };
}


// ===== n8n wrapper (reads fetched CSVs, calls computeRatings, emits upsert rows) =====
const gamesCsv = (() => { try { return $('Get Games CSV').first().json.data || ''; } catch (e) { return ''; } })();
const curCsv   = (() => { try { return $('Get Cur Stats').first().json.data || ''; } catch (e) { return ''; } })();
const priorCsv = (() => { try { return $('Get Prior Stats').first().json.data || ''; } catch (e) { return ''; } })();
const meta = $('Resolve Season Week').first().json;

const { rows, K, week } = computeRatings(curCsv, priorCsv, gamesCsv, meta.season, meta.prior_season);
const computed_at = new Date().toISOString();
const out = rows.map(r => ({ ...r, computed_at }));

return [{ json: { rows: out, count: out.length, season: meta.season, week, K } }];
